// Tiny procedural audio engine — no external assets, all synthesized.
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.muted = false
    this.started = false
    this.lastFoot = 0
  }
  init() {
    if (this.started) return
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    this.started = true
    this.master = this.ctx.createGain(); this.master.gain.value = .55
    this.comp = this.ctx.createDynamicsCompressor()
    this.comp.threshold.value = -20; this.comp.knee.value = 24; this.comp.ratio.value = 8
    this.master.connect(this.comp); this.comp.connect(this.ctx.destination)
    this.noise = this.makeNoise(2)
    this.startAmbient()
  }
  resume() { if (this.ctx?.state === 'suspended') this.ctx.resume() }
  setMuted(v) { this.muted = v; if (this.master) this.master.gain.setTargetAtTime(v ? 0 : .55, this.ctx.currentTime, .1) }
  makeNoise(seconds) {
    const len = this.ctx.sampleRate * seconds
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const d = buf.getChannelData(0)
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1
    return buf
  }
  startAmbient() {
    const ctx = this.ctx
    const g = ctx.createGain(); g.gain.value = .16; g.connect(this.master)
    this.ambientGain = g
    const o1 = ctx.createOscillator(); o1.type = 'sine'; o1.frequency.value = 43.65
    const o2 = ctx.createOscillator(); o2.type = 'triangle'; o2.frequency.value = 65.4
    const o3 = ctx.createOscillator(); o3.type = 'sine'; o3.frequency.value = 87.3
    const lfo = ctx.createOscillator(); lfo.type = 'sine'; lfo.frequency.value = .06
    const lfoG = ctx.createGain(); lfoG.gain.value = 1.6
    lfo.connect(lfoG); lfoG.connect(o2.frequency)
    const og = ctx.createGain(); og.gain.value = .035
    o1.connect(og); o2.connect(og); o3.connect(og); og.connect(g)
    o1.start(); o2.start(); o3.start(); lfo.start()
    // lava rumble
    const src = ctx.createBufferSource(); src.buffer = this.noise; src.loop = true
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 110; f.Q.value = 2
    const ng = ctx.createGain(); ng.gain.value = .11
    const nlfo = ctx.createOscillator(); nlfo.frequency.value = .09
    const nlfoG = ctx.createGain(); nlfoG.gain.value = .05
    nlfo.connect(nlfoG); nlfoG.connect(ng.gain)
    src.connect(f); f.connect(ng); ng.connect(g); src.start(); nlfo.start()
    // distant whispering wind
    const src2 = ctx.createBufferSource(); src2.buffer = this.noise; src2.loop = true
    const f2 = ctx.createBiquadFilter(); f2.type = 'bandpass'; f2.frequency.value = 620; f2.Q.value = .7
    const g2 = ctx.createGain(); g2.gain.value = .014
    src2.connect(f2); f2.connect(g2); g2.connect(g); src2.start()
  }
  tone(freq, dur, type = 'sine', vol = .2, slide = 0, delay = 0) {
    if (!this.ctx || this.muted) return
    const t = this.ctx.currentTime + delay
    const o = this.ctx.createOscillator(); o.type = type
    o.frequency.setValueAtTime(freq, t)
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur)
    const g = this.ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(vol, t + .008); g.gain.exponentialRampToValueAtTime(.0001, t + dur)
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t + dur + .05)
  }
  burst(dur = .12, vol = .2, freq = 800, type = 'lowpass', delay = 0) {
    if (!this.ctx || this.muted) return
    const t = this.ctx.currentTime + delay
    const src = this.ctx.createBufferSource(); src.buffer = this.noise
    const f = this.ctx.createBiquadFilter(); f.type = type; f.frequency.setValueAtTime(freq, t); f.frequency.exponentialRampToValueAtTime(Math.max(80, freq * .3), t + dur)
    const g = this.ctx.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(.0001, t + dur)
    src.connect(f); f.connect(g); g.connect(this.master); src.start(t); src.stop(t + dur + .02)
  }
  footstep(run = false) {
    if (!this.ctx) return
    const now = this.ctx.currentTime
    if (now - this.lastFoot < .22) return
    this.lastFoot = now
    this.burst(.09, run ? .12 : .07, 380 + Math.random() * 120, 'lowpass')
    this.tone(85 + Math.random() * 15, .09, 'sine', .06)
  }
  jump() { this.tone(190, .18, 'triangle', .09, 140); this.burst(.08, .04, 900) }
  swing() { this.burst(.16, .14, 2600, 'bandpass'); this.tone(320, .13, 'sawtooth', .035, -160) }
  bow() { this.tone(440, .1, 'triangle', .09, -200); this.burst(.07, .08, 1800, 'highpass') }
  magic() { this.tone(620, .3, 'sine', .08, 420); this.tone(930, .22, 'sine', .04, 260, .02) }
  hit() { this.tone(70, .16, 'sine', .22, -30); this.burst(.1, .18, 500, 'lowpass') }
  mine() { this.burst(.06, .1, 1500, 'bandpass'); this.tone(240 + Math.random() * 120, .04, 'square', .03) }
  breakBlock() { this.burst(.2, .16, 900, 'lowpass'); this.tone(120, .18, 'triangle', .07, -60) }
  pickup() { this.tone(660, .08, 'sine', .06); this.tone(990, .1, 'sine', .05, 0, .05) }
  craft() { this.tone(330, .12, 'triangle', .08); this.tone(495, .12, 'triangle', .06, 0, .06); this.tone(660, .18, 'sine', .07, 0, .12) }
  hurt() { this.tone(95, .25, 'sawtooth', .14, -35); this.burst(.14, .13, 300, 'lowpass') }
  bossRoar() {
    this.tone(54, 1.6, 'sawtooth', .22, -16); this.tone(81, 1.2, 'square', .09, -24)
    this.burst(1.4, .16, 240, 'lowpass'); this.tone(41, 1.8, 'sine', .2, 8)
  }
  bossDeath() {
    this.tone(60, 2.4, 'sawtooth', .22, -40); this.burst(2.0, .2, 400, 'lowpass')
    this.tone(220, 1.8, 'sine', .08, 660, .2)
  }
  explosion() { this.burst(.6, .28, 1300, 'lowpass'); this.tone(52, .7, 'sine', .22, -30) }
  event() { this.tone(196, .7, 'triangle', .1); this.tone(293.7, .8, 'triangle', .08, 0, .12); this.tone(392, 1.1, 'sine', .09, 0, .24) }
  levelUp() { [523, 659, 784, 1046].forEach((f, i) => this.tone(f, .5, 'triangle', .08, 0, i * .09)) }
  UI() { this.tone(880, .04, 'sine', .025) }
}

import * as THREE from 'three'
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js'
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js'
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js'
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js'
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js'

const SKY_VERT = `
varying vec3 vDir;
void main(){ vDir = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }
`
const SKY_FRAG = `
uniform float uTime;
uniform vec3 uZenith;
uniform vec3 uHorizon;
uniform vec3 uGround;
uniform float uNight;
varying vec3 vDir;
float hash(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }
float noise(vec2 p){ vec2 i=floor(p),f=fract(p); f=f*f*(3.-2.*f); return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y); }
void main(){
  vec3 d = normalize(vDir);
  float up = clamp(d.y, -1.0, 1.0);
  float h = pow(clamp(up, 0.0, 1.0), .55);
  vec3 col = mix(uHorizon, uZenith, h);
  col = mix(uGround, col, smoothstep(-0.16, 0.02, up));
  // distant star field
  vec2 sp = vec2(atan(d.z,d.x), asin(clamp(d.y,-1.,1.))) * 24.0;
  float star = pow(hash(floor(sp)), 34.0);
  star *= smoothstep(.1,.5,up) * (0.55 + 0.45*sin(uTime*2.0 + hash(floor(sp))*30.0));
  col += vec3(.85,.92,1.0) * star * 1.5;
  // drunk-world aurora ribbons
  float ang = atan(d.z,d.x);
  float band = sin(ang*2.3 + d.y*7.0 + uTime*.018) * .5 + .5;
  float band2 = sin(ang*3.9 - d.y*11.0 - uTime*.011) * .5 + .5;
  float aur = smoothstep(.55,1.0,band)*smoothstep(.0,.55,up)*.13 + smoothstep(.78,1.0,band2)*smoothstep(.02,.4,up)*.07;
  vec3 auroraCol = mix(vec3(.82,.27,.82), vec3(.24,.85,.78), smoothstep(.1,.8,up));
  col += auroraCol * aur;
  // celebration haze on horizon
  float cel = smoothstep(.35,.0,abs(up-.06)) * smoothstep(.2,.8,sin(ang*1.7 + 1.2)*.5+.5);
  col += vec3(.34,.12,.22) * cel * .6;
  // moon halo (sprite draws the face)
  vec3 moonDir = normalize(vec3(-.43,.52,-.74));
  float md = max(dot(d,moonDir),0.0);
  col += vec3(1.0,.58,.34) * pow(md, 180.0) * 1.2;
  col += vec3(.7,.26,.22) * pow(md, 18.0) * .10;
  gl_FragColor = vec4(col,1.0);
}
`
const SHAFT_VERT = `
varying vec2 vUv;
varying vec3 vWorld;
void main(){ vUv=uv; vec4 wp=modelMatrix*vec4(position,1.0); vWorld=wp.xyz; gl_Position=projectionMatrix*viewMatrix*wp; }
`
const SHAFT_FRAG = `
uniform float uTime;
uniform vec3 uColor;
uniform float uStrength;
varying vec2 vUv;
varying vec3 vWorld;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x),f.y);}
void main(){
  float edge = smoothstep(0.0,.22,vUv.x)*smoothstep(1.0,.78,vUv.x);
  float vertical = smoothstep(0.0,.16,vUv.y)*smoothstep(1.0,.65,vUv.y);
  float streaks = n(vec2(vUv.x*15.0+uTime*.05, vUv.y*5.0-uTime*.11));
  float a = edge*vertical*(.20 + streaks*.24)*uStrength;
  gl_FragColor = vec4(uColor * (1.0+streaks*.5), a);
}
`
const GRADE_FRAG = `
uniform sampler2D tDiffuse;
uniform float uTime;
uniform vec2 uRes;
varying vec2 vUv;
float rand(vec2 co){ return fract(sin(dot(co,vec2(12.9898,78.233)))*43758.5453); }
void main(){
  vec2 uv = vUv;
  vec2 c = uv - .5;
  float r2 = dot(c,c);
  float ca = .0012 + r2*.0018;
  float r = texture2D(tDiffuse, uv + c*ca).r;
  float g = texture2D(tDiffuse, uv).g;
  float b = texture2D(tDiffuse, uv - c*ca).b;
  vec3 col = vec3(r,g,b);
  // warm highlights, cold crushed shadows
  float l = dot(col, vec3(.299,.587,.114));
  col = mix(col * vec3(.85,.92,1.06), col * vec3(1.10,1.015,.88), smoothstep(.15,.8,l));
  col = mix(vec3(l), col, 1.06);
  float vig = smoothstep(.92,.25,length(c)*1.15);
  col *= mix(.64,1.0,vig);
  col += (rand(uv*uRes + uTime*37.0)-.5)*.018;
  gl_FragColor = vec4(col,1.0);
}
`

function glowTexture(size = 128, inner = 'rgba(255,255,255,1)', outer = 'rgba(255,120,30,0)') {
  const c = document.createElement('canvas'); c.width = c.height = size
  const g = c.getContext('2d')
  const grd = g.createRadialGradient(size / 2, size / 2, 1, size / 2, size / 2, size / 2)
  grd.addColorStop(0, inner); grd.addColorStop(.28, 'rgba(255,190,110,.5)'); grd.addColorStop(1, outer)
  g.fillStyle = grd; g.fillRect(0, 0, size, size)
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t
}

function moonTexture() {
  const size = 512
  const c = document.createElement('canvas'); c.width = c.height = size
  const g = c.getContext('2d')
  // outer sickly halo
  let grd = g.createRadialGradient(256, 256, 100, 256, 256, 256)
  grd.addColorStop(0, 'rgba(255,190,120,.20)'); grd.addColorStop(.55, 'rgba(255,110,60,.08)'); grd.addColorStop(1, 'rgba(255,70,30,0)')
  g.fillStyle = grd; g.fillRect(0, 0, size, size)
  // moon disc
  grd = g.createRadialGradient(222, 222, 24, 262, 262, 176)
  grd.addColorStop(0, '#fff3d4'); grd.addColorStop(.42, '#f0d9ac'); grd.addColorStop(.8, '#c9a77f'); grd.addColorStop(1, '#8f6d59')
  g.fillStyle = grd; g.beginPath(); g.ellipse(262, 258, 170, 174, .06, 0, 7); g.fill()
  // crater stains
  const rnd = (() => { let s = 99; return () => (s = (s * 16807) % 2147483647) / 2147483647 })()
  g.globalAlpha = .18
  for (let i = 0; i < 26; i++) {
    const x = 120 + rnd() * 290, y = 110 + rnd() * 300, r = 7 + rnd() * 26
    const gr = g.createRadialGradient(x, y, 1, x, y, r)
    gr.addColorStop(0, '#5f4436'); gr.addColorStop(1, 'rgba(95,68,54,0)')
    g.fillStyle = gr; g.beginPath(); g.arc(x, y, r, 0, 7); g.fill()
  }
  g.globalAlpha = 1
  // distorted grin
  g.strokeStyle = 'rgba(44,22,26,.88)'; g.lineWidth = 13; g.lineCap = 'round'
  g.beginPath(); g.moveTo(164, 308); g.bezierCurveTo(212, 380, 322, 386, 372, 300); g.stroke()
  g.strokeStyle = 'rgba(255,240,215,.5)'; g.lineWidth = 3
  g.beginPath(); g.moveTo(172, 310); g.bezierCurveTo(218, 372, 320, 378, 364, 304); g.stroke()
  // teeth
  g.fillStyle = 'rgba(50,27,28,.55)'
  for (let i = 0; i < 6; i++) { const x = 196 + i * 28; g.beginPath(); g.moveTo(x, 344 + Math.sin(i) * 4); g.lineTo(x + 12, 337); g.lineTo(x + 14, 356); g.closePath(); g.fill() }
  // eyes — asymmetric crescents
  g.fillStyle = 'rgba(38,20,24,.9)'
  g.beginPath(); g.ellipse(206, 224, 34, 25, -.22, 0, 7); g.fill()
  g.beginPath(); g.ellipse(320, 214, 30, 36, .34, 0, 7); g.fill()
  g.fillStyle = 'rgba(255,225,170,.65)'
  g.beginPath(); g.ellipse(212, 226, 7, 8, 0, 0, 7); g.fill()
  g.beginPath(); g.ellipse(314, 220, 5, 6, 0, 0, 7); g.fill()
  // cracks & drunk distortion
  g.strokeStyle = 'rgba(92,60,54,.35)'; g.lineWidth = 2
  for (let i = 0; i < 7; i++) { g.beginPath(); let x = 160 + rnd() * 220, y = 120 + rnd() * 280; g.moveTo(x, y); for (let j = 0; j < 5; j++) { x += (rnd() - .5) * 24; y += (rnd() - .5) * 20; g.lineTo(x, y) } g.stroke() }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t
}

export class FX {
  constructor(scene, camera, renderer, world, audio) {
    this.scene = scene; this.camera = camera; this.renderer = renderer; this.world = world; this.audio = audio
    this.time = 0
    this.torches = []
    this.torchLights = []
    this.bursts = []
    this.temp = new THREE.Vector3()
    this.setupSky()
    this.setupLights()
    this.setupTorches()
    this.setupParticles()
    this.setupShafts()
    this.setupPost()
  }

  setupSky() {
    const sky = new THREE.Mesh(
      new THREE.SphereGeometry(340, 48, 32),
      new THREE.ShaderMaterial({
        uniforms: {
          uTime: { value: 0 },
          uZenith: { value: new THREE.Color(0x0a0613) },
          uHorizon: { value: new THREE.Color(0x581d24) },
          uGround: { value: new THREE.Color(0x090607) },
          uNight: { value: 1 }
        },
        vertexShader: SKY_VERT, fragmentShader: SKY_FRAG,
        side: THREE.BackSide, depthWrite: false, fog: false
      })
    )
    sky.renderOrder = -1000; this.sky = sky; this.scene.add(sky)

    const starGeo = new THREE.BufferGeometry()
    const starPos = [], starCol = []
    for (let i = 0; i < 900; i++) {
      const theta = Math.random() * Math.PI * 2, phi = Math.acos(Math.random() * .95)
      const r = 315
      starPos.push(Math.sin(phi) * Math.cos(theta) * r, Math.cos(phi) * r * .85 + 10, Math.sin(phi) * Math.sin(theta) * r)
      const b = .45 + Math.random() * .55
      starCol.push(b, b * .92, b * .85)
    }
    starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3))
    starGeo.setAttribute('color', new THREE.Float32BufferAttribute(starCol, 3))
    const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ size: 1.4, vertexColors: true, transparent: true, opacity: .85, depthWrite: false, fog: false, blending: THREE.AdditiveBlending }))
    stars.renderOrder = -999; this.stars = stars; this.scene.add(stars)

    const moonTex = moonTexture()
    const moon = new THREE.Sprite(new THREE.SpriteMaterial({ map: moonTex, transparent: true, depthWrite: false, fog: false, color: 0xffe2c0 }))
    moon.scale.set(76, 76, 1); moon.position.set(-118, 158, -196); moon.renderOrder = -998
    this.moon = moon; this.scene.add(moon)
    const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture(128, 'rgba(255,190,110,.55)', 'rgba(255,90,40,0)'), transparent: true, depthWrite: false, fog: false, blending: THREE.AdditiveBlending, opacity: .65 }))
    halo.scale.set(210, 210, 1); halo.position.copy(moon.position); halo.renderOrder = -999
    this.moonHalo = halo; this.scene.add(halo)
    const moonGroup = new THREE.Group(); moonGroup.add(moon); moonGroup.add(halo); this.scene.add(moonGroup)
    this.moonGroup = moonGroup
  }

  setupLights() {
    this.ambient = new THREE.AmbientLight(0x3a2530, .85); this.scene.add(this.ambient)
    this.hemi = new THREE.HemisphereLight(0x7a4353, 0x190b0b, .8); this.scene.add(this.hemi)
    const sun = new THREE.DirectionalLight(0xffb27a, 1.0)
    sun.position.set(42, 95, 28); sun.target.position.set(32, 40, 32)
    sun.castShadow = true; sun.shadow.mapSize.set(1024, 1024)
    sun.shadow.camera.left = -55; sun.shadow.camera.right = 55; sun.shadow.camera.top = 55; sun.shadow.camera.bottom = -55
    sun.shadow.camera.near = 20; sun.shadow.camera.far = 180; sun.shadow.bias = -0.0006
    this.scene.add(sun); this.scene.add(sun.target); this.sun = sun

    const spot = new THREE.SpotLight(0xff9c54, 900, 46, .52, .62, 1.8)
    spot.position.set(32.5, 21.5, 32.5); spot.target.position.set(32.5, 6.0, 32.5)
    spot.castShadow = true; spot.shadow.mapSize.set(1024, 1024); spot.shadow.bias = -.0009; spot.shadow.camera.near = 1; spot.shadow.camera.far = 36
    this.scene.add(spot); this.scene.add(spot.target); this.spot = spot

    this.altarLight = new THREE.PointLight(0xff6b26, 110, 20, 2)
    this.altarLight.position.set(32.5, 12, 26.5); this.scene.add(this.altarLight)

    const l1 = new THREE.PointLight(0xff5a12, 170, 26, 2); l1.position.set(21, 8.4, 39); this.scene.add(l1); this.lavaLightA = l1
    const l2 = new THREE.PointLight(0xff7020, 140, 24, 2); l2.position.set(41, 8.4, 22); this.scene.add(l2); this.lavaLightB = l2
    const l3 = new THREE.PointLight(0x44f5df, 90, 22, 2); l3.position.set(28, 50, 45); this.scene.add(l3); this.shroomLight = l3
    const l4 = new THREE.PointLight(0xffbf50, 75, 20, 2); l4.position.set(24, 40, 20); this.scene.add(l4); this.hiveLight = l4

    this.torchLightColor = 0xff9a4a
  }

  setupTorches() {
    const glow = glowTexture(128, 'rgba(255,240,190,.95)', 'rgba(255,90,20,0)')
    this.torchGlowTex = glow
    const wood = new THREE.MeshStandardMaterial({ color: 0x5a3a20, roughness: .9 })
    const coal = new THREE.MeshBasicMaterial({ color: 0xffa23a })
    const flameMat = new THREE.SpriteMaterial({ map: glow, color: 0xffb45a, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false })
    for (const p of this.world.torchPositions) {
      const grp = new THREE.Group()
      const stick = new THREE.Mesh(new THREE.CylinderGeometry(.055, .085, .55, 5), wood)
      stick.position.y = -.25; grp.add(stick)
      const ember = new THREE.Mesh(new THREE.ConeGeometry(.1, .22, 5), coal)
      ember.position.y = .08; grp.add(ember)
      const f = new THREE.Sprite(flameMat.clone()); f.scale.set(.9, 1.1, 1); f.position.y = .23; grp.add(f)
      const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: glow, color: 0xff7a30, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: .55 }))
      halo.scale.set(2.2, 2.2, 1); halo.position.y = .2; grp.add(halo)
      grp.position.copy(p); grp.userData.flame = f; grp.userData.halo = halo; grp.userData.seed = Math.random() * 10
      this.scene.add(grp); this.torches.push(grp)
    }
    for (let i = 0; i < 4; i++) {
      const l = new THREE.PointLight(0xff9a4a, 46, 12, 2)
      this.scene.add(l); this.torchLights.push(l)
    }
    this.torchAssignTimer = 0
  }

  addTorch(pos) {
    const glow = this.torchGlowTex
    const wood = new THREE.MeshStandardMaterial({ color: 0x5a3a20, roughness: .9 })
    const coal = new THREE.MeshBasicMaterial({ color: 0xffa23a })
    const grp = new THREE.Group()
    const stick = new THREE.Mesh(new THREE.CylinderGeometry(.055, .085, .55, 5), wood); stick.position.y = -.25; grp.add(stick)
    const ember = new THREE.Mesh(new THREE.ConeGeometry(.1, .22, 5), coal); ember.position.y = .08; grp.add(ember)
    const f = new THREE.Sprite(new THREE.SpriteMaterial({ map: glow, color: 0xffb45a, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false })); f.scale.set(.9, 1.1, 1); f.position.y = .23; grp.add(f)
    const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: glow, color: 0xff7a30, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: .55 })); halo.scale.set(2.2, 2.2, 1); halo.position.y = .2; grp.add(halo)
    grp.position.copy(pos); grp.userData.flame = f; grp.userData.halo = halo; grp.userData.seed = Math.random() * 10
    this.scene.add(grp); this.torches.push(grp)
    return grp
  }

  setupParticles() {
    const makePoints = (count, colorA, colorB, size, opacity, blending = THREE.AdditiveBlending) => {
      const geo = new THREE.BufferGeometry()
      const pos = new Float32Array(count * 3), col = new Float32Array(count * 3)
      const cA = new THREE.Color(colorA), cB = new THREE.Color(colorB)
      for (let i = 0; i < count; i++) {
        pos[i * 3] = (Math.random() - .5) * 38
        pos[i * 3 + 1] = 4 + Math.random() * 16
        pos[i * 3 + 2] = (Math.random() - .5) * 38
        const c = cA.clone().lerp(cB, Math.random())
        col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b
      }
      geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
      geo.setAttribute('color', new THREE.BufferAttribute(col, 3))
      const mat = new THREE.PointsMaterial({ map: this.torchGlowTex, size, vertexColors: true, transparent: true, opacity, depthWrite: false, blending, sizeAttenuation: true })
      const pts = new THREE.Points(geo, mat); pts.frustumCulled = false; this.scene.add(pts)
      return { pts, pos, count, baseY: 4, height: 18, origin: new THREE.Vector3(32, 0, 32) }
    }
    this.embers = makePoints(420, 0xffc36b, 0xff4b12, .18, .85)
    this.embers.origin.set(32, 0, 32); this.embers.baseY = 4; this.embers.height = 18
    this.ash = makePoints(220, 0x9b8a7c, 0x50423d, .11, .48, THREE.NormalBlending)
    this.ash.origin.set(32, 0, 32); this.ash.baseY = 8; this.ash.height = 13
    this.spores = makePoints(180, 0x7dffe8, 0x1c9cff, .13, .8)
    this.spores.origin.set(28, 45, 45); this.spores.baseY = 43; this.spores.height = 12
    this.surfaceMotes = makePoints(130, 0xffe7bd, 0xff9f6a, .09, .4)
    this.surfaceMotes.origin.set(32, 0, 32); this.surfaceMotes.baseY = 50; this.surfaceMotes.height = 20
    // ember geysers over lava
    this.lavaGlows = []
    for (const [x, z, s] of [[18, 36, 13], [46, 22, 11], [32, 50, 10], [10, 32, 9], [54, 40, 8]]) {
      const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture(128, 'rgba(255,150,60,.6)', 'rgba(255,50,10,0)'), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: .28 }))
      sp.position.set(x, 7.4, z); sp.scale.set(s, s * .45, 1); this.scene.add(sp); this.lavaGlows.push(sp)
    }
    // spark pool
    const N = 300
    const g = new THREE.BufferGeometry()
    this.sparkPos = new Float32Array(N * 3).fill(9999)
    this.sparkCol = new Float32Array(N * 3)
    this.sparkVel = new Float32Array(N * 3)
    this.sparkLife = new Float32Array(N)
    g.setAttribute('position', new THREE.BufferAttribute(this.sparkPos, 3))
    g.setAttribute('color', new THREE.BufferAttribute(this.sparkCol, 3))
    this.sparkPoints = new THREE.Points(g, new THREE.PointsMaterial({ size: .16, vertexColors: true, transparent: true, opacity: .95, blending: THREE.AdditiveBlending, depthWrite: false, map: this.torchGlowTex }))
    this.sparkPoints.frustumCulled = false; this.scene.add(this.sparkPoints); this.sparkIndex = 0
  }

  setupShafts() {
    const mat = new THREE.ShaderMaterial({
      uniforms: { uTime: { value: 0 }, uColor: { value: new THREE.Color(0xffb073) }, uStrength: { value: 1 } },
      vertexShader: SHAFT_VERT, fragmentShader: SHAFT_FRAG,
      transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide
    })
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(2.6, 6.2, 16, 32, 1, true), mat)
    shaft.position.set(32.5, 13.5, 32.5); shaft.renderOrder = 5; this.scene.add(shaft); this.shaft = shaft
    const mat2 = mat.clone(); mat2.uniforms.uColor.value = new THREE.Color(0xffd6a1); mat2.uniforms.uStrength.value = .55
    const shaft2 = new THREE.Mesh(new THREE.CylinderGeometry(1.2, 3.4, 42, 24, 1, true), mat2)
    shaft2.position.set(45.5, 38, 33.5); this.scene.add(shaft2); this.shaft2 = shaft2
    this.shaftMat = mat; this.shaftMat2 = mat2
  }

  setupPost() {
    const composer = new EffectComposer(this.renderer)
    this.renderPass = new RenderPass(this.scene, this.camera)
    composer.addPass(this.renderPass)
    this.bloom = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), .82, .62, .78)
    composer.addPass(this.bloom)
    const grade = new ShaderPass({
      uniforms: { tDiffuse: { value: null }, uTime: { value: 0 }, uRes: { value: new THREE.Vector2(window.innerWidth, window.innerHeight) } },
      vertexShader: `varying vec2 vUv; void main(){ vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
      fragmentShader: GRADE_FRAG
    })
    composer.addPass(grade)
    composer.addPass(new OutputPass())
    this.composer = composer; this.grade = grade
    this.quality = 1
  }

  resize(w, h) {
    this.composer.setSize(w, h)
    this.bloom.setSize(w, h)
    this.grade.uniforms.uRes.value.set(w, h)
  }

  setQuality(q) {
    this.quality = q
    this.bloom.enabled = q > .45
    if (q < .55) this.renderer.setPixelRatio(1)
  }

  spawnBurst(pos, color = 0xffa04a, count = 18, speed = 5, size = .14) {
    const c = new THREE.Color(color)
    for (let i = 0; i < count; i++) {
      const idx = this.sparkIndex = (this.sparkIndex + 1) % this.sparkLife.length
      const p = idx * 3
      this.sparkPos[p] = pos.x + (Math.random() - .5) * .35
      this.sparkPos[p + 1] = pos.y + (Math.random() - .5) * .35
      this.sparkPos[p + 2] = pos.z + (Math.random() - .5) * .35
      const dir = new THREE.Vector3(Math.random() - .5, Math.random() - .25, Math.random() - .5).normalize().multiplyScalar(speed * (.35 + Math.random()))
      this.sparkVel[p] = dir.x; this.sparkVel[p + 1] = dir.y; this.sparkVel[p + 2] = dir.z
      this.sparkCol[p] = c.r; this.sparkCol[p + 1] = c.g; this.sparkCol[p + 2] = c.b
      this.sparkLife[idx] = .5 + Math.random() * .7
    }
    this.sparkPoints.geometry.attributes.position.needsUpdate = true
    this.sparkPoints.geometry.attributes.color.needsUpdate = true
  }

  update(dt, time, player) {
    this.time = time
    this.sky.position.copy(this.camera.position)
    this.stars.position.copy(this.camera.position)
    this.sky.material.uniforms.uTime.value = time
    this.stars.rotation.y = time * .002
    const day = (Math.sin(time * .012) + 1) * .5
    this.sky.material.uniforms.uZenith.value.setHSL(.76, .55, .035 + .03 * day)
    this.sky.material.uniforms.uHorizon.value.setHSL(.035 + day * .02, .52, .16 + .13 * day)
    this.moonGroup.rotation.y = Math.sin(time * .006) * .18
    this.moonGroup.position.set(Math.sin(time * .013) * 8, Math.cos(time * .009) * 4, 0)
    this.moon.material.color.setHSL(.09, .45, .78 + day * .16)
    this.moonHalo.material.opacity = .45 + day * .18

    // torches flicker
    for (const t of this.torches) {
      const s = t.userData.seed
      const fl = .86 + Math.sin(time * 8 + s) * .09 + Math.sin(time * 19 + s * 3) * .05
      if (t.userData.flame) t.userData.flame.scale.set(.78 * fl, 1.02 * fl, 1)
      if (t.userData.halo) t.userData.halo.material.opacity = .4 * fl + .1
    }
    this.torchAssignTimer -= dt
    if (this.torchAssignTimer <= 0 && player) {
      this.torchAssignTimer = .4
      const sorted = this.torches.map(t => ({ t, d: t.position.distanceToSquared(player.position) })).sort((a, b) => a.d - b.d).slice(0, this.torchLights.length)
      this.torchLights.forEach((l, i) => {
        if (sorted[i]) { l.position.copy(sorted[i].t.position); l.position.y += .4; l.intensity = 44; l.distance = 11 } else l.intensity = 0
      })
    }
    for (const l of this.torchLights) l.intensity *= .96 + Math.sin(time * 9 + l.position.x) * .02

    // particles
    this.updateParticles(this.embers, dt, time, .9, 1.6)
    this.updateParticles(this.ash, dt, time, .25, .6, true)
    this.updateParticles(this.spores, dt, time, .18, .5)
    this.updateParticles(this.surfaceMotes, dt, time, .22, .55)
    for (const sp of this.lavaGlows) { sp.material.opacity = .2 + Math.sin(time * 1.3 + sp.position.x) * .07 }

    // sparks
    let any = false
    for (let i = 0; i < this.sparkLife.length; i++) {
      if (this.sparkLife[i] <= 0) continue
      any = true
      const p = i * 3
      this.sparkLife[i] -= dt
      if (this.sparkLife[i] <= 0) { this.sparkPos[p] = 9999; this.sparkPos[p + 1] = 9999; this.sparkPos[p + 2] = 9999; continue }
      this.sparkVel[p + 1] -= 9.5 * dt
      this.sparkPos[p] += this.sparkVel[p] * dt; this.sparkPos[p + 1] += this.sparkVel[p + 1] * dt; this.sparkPos[p + 2] += this.sparkVel[p + 2] * dt
    }
    if (any) { this.sparkPoints.geometry.attributes.position.needsUpdate = true; this.sparkPoints.geometry.attributes.color.needsUpdate = true }

    this.shaftMat.uniforms.uTime.value = time
    this.shaftMat2.uniforms.uTime.value = time
    this.grade.uniforms.uTime.value = time
    this.altarLight.intensity = 100 + Math.sin(time * 2.2) * 16 + Math.sin(time * 7.1) * 8
    this.lavaLightA.intensity = 150 + Math.sin(time * 1.8) * 22
    this.lavaLightB.intensity = 125 + Math.sin(time * 2.3 + 2) * 18

    // depth driven lighting
    if (player) {
      const y = player.position.y
      const surf = THREE.MathUtils.smoothstep(y, 42, 62)
      this.sun.intensity = .04 + surf * 1.7
      this.hemi.intensity = .55 + surf * .5
      this.ambient.intensity = .72 - surf * .3
      this.spot.intensity = 760 + Math.sin(time * 3) * 20
      this.scene.fog.color.lerpColors(new THREE.Color(0x150a09), new THREE.Color(0x3a2228), surf)
      this.scene.fog.density = .044 - surf * .032
      this.scene.background = null
    }
  }

  updateParticles(sys, dt, time, speed, drift, down = false) {
    const { pos, count } = sys
    for (let i = 0; i < count; i++) {
      const p = i * 3
      pos[p + 1] += (down ? -1 : 1) * speed * dt * (0.5 + (i % 7) * .13)
      pos[p] += Math.sin(time * .7 + i) * drift * dt
      pos[p + 2] += Math.cos(time * .53 + i * 1.7) * drift * dt
      if (!down && pos[p + 1] > sys.baseY + sys.height) pos[p + 1] = sys.baseY
      if (down && pos[p + 1] < sys.baseY) pos[p + 1] = sys.baseY + sys.height
      if (pos[p] > 19 || pos[p] < -19) pos[p] = (Math.random() - .5) * 38
      if (pos[p + 2] > 19 || pos[p + 2] < -19) pos[p + 2] = (Math.random() - .5) * 38
    }
    sys.pts.position.set(sys.origin.x, 0, sys.origin.z)
    sys.pts.geometry.attributes.position.needsUpdate = true
  }

  render() { this.composer.render() }
}

import { ITEMS, RECIPES, HOTBAR, itemDef, itemIconHTML } from './items.js'

export class UI {
  constructor(game) {
    this.game = game
    this.el = id => document.getElementById(id)
    this.cache()
    this.selTab = 'weapons'
    this.toastList = []
    this.bannerTimer = 0
    this.fpsAcc = 0; this.fpsFrames = 0; this.fpsShown = 60
    this.godElapsed = 0
    this.lastMinimap = 0
    this.bind()
    this.buildHotbar()
    this.renderStations()
    this.renderCrafting()
    this.renderInventory()
  }

  cache() {
    const ids = ['hud', 'objective-text', 'objective-sub', 'depth-value', 'biome-value', 'minimap-label',
      'hp-fill', 'hp-text', 'mana-fill', 'mana-text', 'hotbar', 'weapon-name', 'mine-wrap', 'mine-fill', 'mine-label',
      'interact', 'interact-text', 'boss-wrap', 'boss-name', 'boss-fill', 'boss-phase', 'toasts', 'event-banner',
      'event-kicker', 'event-title', 'damage-flash', 'lava-flash', 'clock-text', 'clock-icon', 'fps-text',
      'q-kills', 'q-blocks', 'q-crystals', 'inventory', 'inv-grid', 'inv-capacity', 'craft-list', 'craft-tabs',
      'station-row', 'ritual', 'help', 'death', 'death-cause', 'respawn-btn', 'touch', 'buff-flight', 'buff-bed',
      'buff-grapple', 'minimap']
    for (const id of ids) this[id] = document.getElementById(id)
    this.ctx = this.minimap.getContext('2d')
  }

  bind() {
    document.querySelectorAll('[data-close]').forEach(b => b.addEventListener('click', () => this.closeOverlay(b.dataset.close)))
    document.querySelectorAll('.craft-tabs button').forEach(b => b.addEventListener('click', () => {
      this.selTab = b.dataset.tab
      document.querySelectorAll('.craft-tabs button').forEach(x => x.classList.toggle('active', x === b))
      this.renderCrafting(); this.game.audio.UI()
    }))
    document.querySelectorAll('.ritual-card').forEach(b => b.addEventListener('click', () => {
      this.game.summonBoss(b.dataset.boss); this.closeOverlay('ritual'); this.game.audio.UI()
    }))
    this.respawnBtn.addEventListener('click', () => this.game.respawn())
    // first click on canvas -> pointer lock / audio
    this.game.canvas.addEventListener('pointerdown', () => { if (!this.isOverlayOpen()) this.game.requestLock() })
    // Touch controls
    this.setupTouch()
    window.addEventListener('keydown', e => {
      if (e.code === 'Tab') { e.preventDefault(); this.toggleInventory() }
      else if (e.code === 'KeyH' && !this.isOverlayOpen()) { this.openOverlay('help') }
      else if (e.code === 'Escape') { if (this.isOverlayOpen()) this.closeAll(); else document.exitPointerLock?.() }
    })
  }

  isOverlayOpen() { return !this.inventory.classList.contains('hidden') || !this.ritual.classList.contains('hidden') || !this.help.classList.contains('hidden') || !this.death.classList.contains('hidden') }
  openOverlay(id) {
    document.exitPointerLock?.()
    this[id].classList.remove('hidden')
    this.game.paused = true
    if (id === 'inventory') { this.renderInventory(); this.renderStations(); this.renderCrafting() }
    if (id === 'ritual') this.renderRitual()
    this.game.audio.UI()
  }
  closeOverlay(id) {
    this[id]?.classList.add('hidden')
    if (!this.isOverlayOpen()) { this.game.paused = false; this.game.requestLock() }
    this.game.audio.UI()
  }
  closeAll() { for (const id of ['inventory', 'ritual', 'help']) this[id].classList.add('hidden'); this.game.paused = false }
  toggleInventory() { if (this.inventory.classList.contains('hidden')) this.openOverlay('inventory'); else this.closeOverlay('inventory') }
  openRitual() { this.openOverlay('ritual') }

  setVisible(v) { this.hud.classList.toggle('hidden', !v); this.touch.classList.toggle('hidden', !(v && this.game.isTouch)) }

  buildHotbar() {
    const inv = this.game.inventory
    this.hotbar.innerHTML = ''
    this.game.hotbar.forEach((name, i) => {
      const s = document.createElement('div')
      s.className = 'slot' + (i === this.game.selected ? ' active' : '')
      s.dataset.slot = i
      const def = itemDef(name)
      const count = name === 'Ember Blade' || name === 'Demon Bow' || name === 'Starfall Staff' || name === 'Pickaxe' ? '' : (inv.get(name) || 0)
      s.innerHTML = `<span class="slot-key">${i + 1}</span><span class="slot-icon">${itemIconHTML(name, 25)}</span>${count !== '' ? `<span class="slot-count">${count}</span>` : ''}<span class="slot-name">${name}</span>`
      s.title = def.desc
      s.addEventListener('click', () => { this.game.selectSlot(i); this.game.audio.UI() })
      this.hotbar.appendChild(s)
    })
  }

  refreshHotbar() {
    const inv = this.game.inventory
    ;[...this.hotbar.children].forEach((s, i) => {
      const name = this.game.hotbar[i]
      s.classList.toggle('active', i === this.game.selected)
      const def = itemDef(name)
      const countEl = s.querySelector('.slot-count')
      const count = name === 'Ember Blade' || name === 'Demon Bow' || name === 'Starfall Staff' || name === 'Pickaxe' ? '' : (inv.get(name) || 0)
      if (countEl) countEl.textContent = count
      else if (count !== '') { const c = document.createElement('span'); c.className = 'slot-count'; c.textContent = count; s.appendChild(c) }
      s.title = def.desc
    })
  }

  renderInventory() {
    const inv = this.game.inventory
    this.invGrid.innerHTML = ''
    const entries = [...inv.entries()].filter(([, c]) => c > 0)
    const total = entries.reduce((a, [, c]) => a + c, 0)
    this.invCapacity.textContent = `${Math.min(30, entries.length)} / 30 · ${total} ITEMS`
    for (let i = 0; i < 30; i++) {
      const slot = document.createElement('div')
      slot.className = 'inv-slot'
      const entry = entries[i]
      if (entry) {
        const [name, count] = entry
        const def = itemDef(name)
        slot.classList.add('has')
        slot.title = `${def.name}\n${def.desc}`
        slot.innerHTML = `<span class="in">${name.slice(0, 12)}</span><span class="ii">${itemIconHTML(name, 22)}</span><span class="ic">${count}</span>`
        if (this.game.hotbar.includes(name) && this.game.selected === this.game.hotbar.indexOf(name)) slot.classList.add('selected')
        slot.addEventListener('click', () => { this.game.onInventoryItemClick(name); this.renderInventory(); this.refreshHotbar(); this.game.audio.UI() })
      }
      this.invGrid.appendChild(slot)
    }
  }

  renderStations() {
    const st = this.game.stations
    const defs = [['workbench', 'WORK BENCH'], ['loom', 'LOOM'], ['sawmill', 'SAWMILL'], ['anvil', 'ANVIL']]
    this.stationRow.innerHTML = defs.map(([k, n]) => `<span class="station ${st[k] ? 'on' : ''}">${st[k] ? '◆' : '◇'} ${n}</span>`).join('')
  }

  renderCrafting() {
    const recs = RECIPES.filter(r => r.tab === this.selTab)
    this.craftList.innerHTML = recs.map(r => {
      const def = itemDef(r.item)
      const missingStation = r.station.some(s => !this.game.stations[s])
      const missingMats = Object.entries(r.cost).filter(([k, v]) => (this.game.inventory.get(k) || 0) < v)
      const can = !missingStation && missingMats.length === 0
      const cost = Object.entries(r.cost).map(([k, v]) => {
        const have = this.game.inventory.get(k) || 0
        return `<span class="${have < v ? 'miss' : ''}">${k} ${have}/${v}</span>`
      }).join(' · ')
      return `<div class="recipe ${can ? '' : 'locked'}" data-id="${r.id}">
        <div class="recipe-icon">${itemIconHTML(r.item, 20)}</div>
        <div><div class="recipe-name">${r.item}${r.count > 1 ? ' ×' + r.count : ''}</div><div class="recipe-desc">${r.desc}</div><div class="recipe-cost">${cost}${missingStation ? ` · <span class="miss">needs ${r.station.map(s => s.toUpperCase()).join(' + ')}</span>` : ''}</div></div>
        <button class="craft-btn" ${can ? '' : 'disabled'} data-craft="${r.id}">CRAFT</button>
      </div>`
    }).join('')
    this.craftList.querySelectorAll('.craft-btn').forEach(b => b.addEventListener('click', e => {
      e.stopPropagation(); this.game.craft(b.dataset.craft)
      this.renderInventory(); this.renderStations(); this.renderCrafting(); this.refreshHotbar()
    }))
  }

  renderRitual() {
    const dead = this.game.defeatedBosses
    document.querySelectorAll('.ritual-card').forEach(c => {
      const t = c.dataset.boss
      const done = dead[t]
      c.querySelector('em').textContent = done ? 'DEFEATED' : 'SUMMON'
      c.style.opacity = done ? '.6' : ''
    })
  }

  setSelection() {
    const name = this.game.hotbar[this.game.selected]
    this.weaponName.textContent = (itemDef(name).name || name).toUpperCase()
    this.refreshHotbar()
    this.buildHotbar()
  }

  update(player, game, dt) {
    this.fpsAcc += dt; this.fpsFrames++
    if (this.fpsAcc > .5) { this.fpsShown = Math.round(this.fpsFrames / this.fpsAcc); this.fpsAcc = 0; this.fpsFrames = 0; this.fpsText.textContent = `${this.fpsShown} FPS` }
    this.hpFill.style.width = `${Math.max(0, player.health / player.maxHealth * 100)}%`
    this.hpText.textContent = `${Math.ceil(player.health)} / ${player.maxHealth}`
    this.manaFill.style.width = `${Math.max(0, player.mana / player.maxMana * 100)}%`
    this.manaText.textContent = `${Math.floor(player.mana)} / ${player.maxMana}`
    const ground = game.world.surfaceHeight(Math.floor(player.position.x), Math.floor(player.position.z))
    const depth = Math.round(player.position.y - 8)
    const biome = this.biomeAt(player, ground)
    this.depthValue.textContent = depth <= 0 ? 'ABYSS' : `${depth} m`
    this.biomeValue.textContent = biome.name
    this.minimapLabel.textContent = biome.label
    if (game.boss) {
      this.bossWrap.classList.remove('hidden')
      this.bossName.textContent = game.boss.name
      this.bossFill.style.width = `${Math.max(0, game.boss.hp / game.boss.maxHp * 100)}%`
      this.bossPhase.textContent = game.boss.phaseText
    } else this.bossWrap.classList.add('hidden')
    this.qKills.textContent = game.stats.kills
    this.qBlocks.textContent = game.stats.blocks
    this.qCrystals.textContent = `${game.stats.crystals}/5`
    this.buffFlight.classList.toggle('on', player.wings)
    this.buffBed.classList.toggle('on', !!game.bedPos)
    this.buffGrapple.classList.toggle('on', true)
    const hour = Math.floor(((game.dayTime + .25) % 1) * 24)
    this.clockText.textContent = `${String(hour).padStart(2, '0')}:00`
    this.clockIcon.textContent = hour >= 6 && hour < 19 ? '☀' : '☾'
    if (game.interactText) { this.interactText.textContent = game.interactText; this.interact.classList.remove('hidden') } else this.interact.classList.add('hidden')
    if (game.mining) {
      this.mineWrap.classList.remove('hidden'); this.mineFill.style.width = `${Math.min(100, game.mining.progress * 100)}%`; this.mineLabel.textContent = `MINING ${game.mining.name.toUpperCase()}`
    } else this.mineWrap.classList.add('hidden')
    if (this.bannerTimer > 0) { this.bannerTimer -= dt; if (this.bannerTimer <= 0) this.eventBanner.classList.add('hidden') }
    this.drawMinimap(game, player, dt)
    this.refreshHotbar()
    if (game.inventoryDirty) { this.renderInventory(); this.renderStations(); this.renderCrafting(); game.inventoryDirty = false }
  }

  biomeAt(player, ground) {
    const y = player.position.y, x = player.position.x
    if (y > ground - 3) return { name: 'CELEBRATION BEACH', label: 'SURFACE · BEACH' }
    if (y > 48) return { name: 'MUSHROOM GROVE', label: 'THE GLOWING DEEP' }
    if (y > 36) return { name: 'NOT THE BEES', label: 'HIVE LAYER' }
    if (y > 18) return x < 32 ? { name: 'THE CORRUPTION', label: 'CORRUPTED STRATA' } : { name: 'THE CRIMSON', label: 'CRIMSON STRATA' }
    if (y > 8) return { name: 'ASHEN CAVERNS', label: 'THE UNDERWORLD' }
    return { name: 'THE UNDERWORLD', label: 'THE UNDERWORLD' }
  }

  drawMinimap(game, player, dt) {
    this.godElapsed += dt
    if (this.godElapsed < .09) return
    this.godElapsed = 0
    const ctx = this.ctx, size = 184
    ctx.clearRect(0, 0, size, size)
    ctx.fillStyle = '#080506'; ctx.fillRect(0, 0, size, size)
    ctx.save(); ctx.translate(size / 2, size / 2); ctx.rotate(-player.yaw)
    const cell = 5, radius = 18
    const px = Math.floor(player.position.x), pz = Math.floor(player.position.z)
    for (let dz = -radius; dz <= radius; dz++) for (let dx = -radius; dx <= radius; dx++) {
      const wx = px + dx, wz = pz + dz
      const c = game.world.mapPixel(wx, wz)
      ctx.fillStyle = c
      ctx.fillRect(dx * cell, dz * cell, cell + .5, cell + .5)
    }
    // lava shimmer markers
    ctx.globalAlpha = .55
    for (const l of game.fx.lavaGlows) {
      const dx = l.position.x - px, dz = l.position.z - pz
      if (Math.abs(dx) < radius && Math.abs(dz) < radius) { ctx.fillStyle = '#ff8a2e'; ctx.fillRect(dx * cell - 2, dz * cell - 2, 6, 6) }
    }
    ctx.globalAlpha = 1
    // enemies
    for (const e of game.enemies.list) {
      const dx = e.position.x - px, dz = e.position.z - pz
      if (Math.abs(dx) < radius && Math.abs(dz) < radius) { ctx.fillStyle = '#ff3f4a'; ctx.fillRect(dx * cell - 1.5, dz * cell - 1.5, 4, 4) }
    }
    if (game.boss) {
      const dx = game.boss.root.position.x - px, dz = game.boss.root.position.z - pz
      ctx.fillStyle = '#ffcf5b'; ctx.beginPath(); ctx.arc(dx * cell, dz * cell, 4, 0, 7); ctx.fill()
    }
    ctx.restore()
    // player arrow
    ctx.save(); ctx.translate(size / 2, size / 2)
    ctx.fillStyle = '#ffdca5'; ctx.shadowColor = '#ff7a2a'; ctx.shadowBlur = 8
    ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(5, 5); ctx.lineTo(0, 2); ctx.lineTo(-5, 5); ctx.closePath(); ctx.fill()
    ctx.restore()
  }

  toast(text, type = '') {
    const el = document.createElement('div'); el.className = `toast ${type}`; el.textContent = text
    this.toasts.appendChild(el)
    while (this.toasts.children.length > 6) this.toasts.removeChild(this.toasts.firstChild)
    setTimeout(() => { el.style.opacity = '0'; el.style.transform = 'translateY(-4px)'; setTimeout(() => el.remove(), 400) }, 3200)
  }

  banner(kicker, title, seconds = 4.5) {
    this.eventKicker.textContent = kicker; this.eventTitle.textContent = title
    this.eventBanner.classList.remove('hidden'); this.bannerTimer = seconds
    this.eventBanner.style.animation = 'none'; void this.eventBanner.offsetWidth; this.eventBanner.style.animation = 'eventIn .5s ease both'
  }

  flashDamage() {
    this.damageFlash.style.opacity = '.9'
    setTimeout(() => this.damageFlash.style.opacity = '0', 60)
  }
  flashLava() {
    this.lavaFlash.style.opacity = '.8'
    setTimeout(() => this.lavaFlash.style.opacity = '0', 90)
  }
  setMining() { }

  showDeath(cause) {
    this.deathCause.textContent = cause
    this.death.classList.remove('hidden')
    this.game.paused = true
    document.exitPointerLock?.()
  }
  hideDeath() { this.death.classList.add('hidden'); this.game.paused = false; this.requestLockSoon() }
  requestLockSoon() { setTimeout(() => this.game.requestLock(), 120) }

  setupTouch() {
    const stick = document.getElementById('touch-stick'), knob = stick.querySelector('i')
    let active = false, id = null, cx = 0, cy = 0
    const setAxis = (x, y) => { this.game.touchMove.set(x, y) }
    stick.addEventListener('pointerdown', e => { active = true; id = e.pointerId; const r = stick.getBoundingClientRect(); cx = r.left + r.width / 2; cy = r.top + r.height / 2; stick.setPointerCapture(id) })
    stick.addEventListener('pointermove', e => {
      if (!active || e.pointerId !== id) return
      let dx = (e.clientX - cx) / 44, dy = (e.clientY - cy) / 44
      const l = Math.hypot(dx, dy); if (l > 1) { dx /= l; dy /= l }
      knob.style.transform = `translate(${dx * 28}px,${dy * 28}px)`
      setAxis(dx, -dy)
    })
    const end = e => { if (e.pointerId !== id) return; active = false; knob.style.transform = ''; setAxis(0, 0) }
    stick.addEventListener('pointerup', end); stick.addEventListener('pointercancel', end)
    const look = document.getElementById('touch-look')
    let lid = null, lx = 0, ly = 0
    look.addEventListener('pointerdown', e => { lid = e.pointerId; lx = e.clientX; ly = e.clientY; look.setPointerCapture(lid) })
    look.addEventListener('pointermove', e => {
      if (e.pointerId !== lid) return
      const dx = e.clientX - lx, dy = e.clientY - ly; lx = e.clientX; ly = e.clientY
      this.game.player.look(dx * 2.2, dy * 2.2)
    })
    look.addEventListener('pointerup', () => { lid = null })
    document.querySelectorAll('[data-touch]').forEach(b => {
      b.addEventListener('pointerdown', e => {
        e.preventDefault(); const a = b.dataset.touch
        if (a === 'inventory') this.toggleInventory()
        else if (a === 'jump') this.game.player.touchJump()
        else if (a === 'attack') this.game.player.attack()
        else if (a === 'mine') { this.game.player.setMining(true); setTimeout(() => this.game.player.setMining(false), 650) }
        else if (a === 'dash') this.game.player.dash()
        else if (a === 'grapple') this.game.player.grapple()
      })
    })
  }
}

import * as THREE from 'three'
import { B } from './blocks.js'

const rand = (a, b) => a + Math.random() * (b - a)
const V = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z)

function basicMat(color, emissive = 0, intensity = 0) {
  return new THREE.MeshStandardMaterial({ color, roughness: .55, metalness: .05, emissive, emissiveIntensity: intensity })
}
function glowSprite(color, scale = 1, opacity = .7) {
  const c = document.createElement('canvas'); c.width = c.height = 64
  const g = c.getContext('2d'); const gr = g.createRadialGradient(32, 32, 1, 32, 32, 32)
  gr.addColorStop(0, 'rgba(255,255,255,.95)'); gr.addColorStop(.3, 'rgba(255,255,255,.45)'); gr.addColorStop(1, 'rgba(255,255,255,0)')
  g.fillStyle = gr; g.fillRect(0, 0, 64, 64)
  const t = new THREE.CanvasTexture(c)
  return new THREE.Sprite(new THREE.SpriteMaterial({ map: t, color, transparent: true, opacity, blending: THREE.AdditiveBlending, depthWrite: false }))
}

/* ============================ PROJECTILES ============================ */
export class Projectile {
  constructor(game, opts) {
    this.game = game
    this.owner = opts.owner
    this.damage = opts.damage || 10
    this.velocity = opts.velocity.clone()
    this.gravity = opts.gravity ?? 0
    this.homing = opts.homing || 0
    this.life = opts.life ?? 5
    this.radius = opts.radius || .18
    this.color = opts.color ?? 0xffa040
    this.kind = opts.kind || 'bolt'
    this.dead = false
    this.trailPts = []
    this.root = new THREE.Group()
    const c = new THREE.Color(this.color)
    if (this.kind === 'arrow') {
      const shaft = new THREE.Mesh(new THREE.CylinderGeometry(.025, .025, .8, 5), new THREE.MeshStandardMaterial({ color: 0x8f6a45, roughness: .8 }))
      shaft.rotation.x = Math.PI / 2; this.root.add(shaft)
      const tip = new THREE.Mesh(new THREE.ConeGeometry(.055, .16, 5), new THREE.MeshStandardMaterial({ color: this.color, emissive: this.color, emissiveIntensity: .6 }))
      tip.position.z = .42; tip.rotation.x = Math.PI / 2; this.root.add(tip)
      const sp = glowSprite(this.color, .45, .35); this.root.add(sp)
    } else if (this.kind === 'stinger') {
      const cone = new THREE.Mesh(new THREE.ConeGeometry(.1, .45, 6), new THREE.MeshStandardMaterial({ color: 0xffcf6a, emissive: 0x572b08, emissiveIntensity: .4 }))
      cone.rotation.x = Math.PI / 2; this.root.add(cone)
    } else {
      const core = new THREE.Mesh(new THREE.SphereGeometry(this.radius, 10, 8), new THREE.MeshBasicMaterial({ color: this.color }))
      this.root.add(core)
      const sp = glowSprite(this.color, this.radius * 7, .9); this.root.add(sp)
    }
    this.root.position.copy(opts.position)
    game.scene.add(this.root)
    const trailGeo = new THREE.BufferGeometry()
    trailGeo.setAttribute('position', new THREE.Float32BufferAttribute(new Float32Array(24), 3))
    this.trail = new THREE.Line(trailGeo, new THREE.LineBasicMaterial({ color: this.color, transparent: true, opacity: .4, blending: THREE.AdditiveBlending, depthWrite: false }))
    this.trail.frustumCulled = false
    game.scene.add(this.trail)
    this.trailTimer = 0
  }
  update(dt) {
    if (this.dead) return
    this.life -= dt
    if (this.life <= 0) return this.kill(false)
    if (this.homing) {
      const target = this.owner === 'player' ? this.game.enemies.nearest(this.root.position) : this.game.player.position
      if (target) {
        const desired = (this.owner === 'player' ? target : target.clone().add(V(0, .9, 0))).sub(this.root.position).normalize().multiplyScalar(this.velocity.length())
        this.velocity.lerp(desired, Math.min(1, this.homing * dt))
      }
    }
    this.velocity.y -= this.gravity * dt
    const old = this.root.position.clone()
    const step = this.velocity.clone().multiplyScalar(dt)
    const steps = Math.max(1, Math.ceil(step.length() / .25))
    for (let s = 0; s < steps; s++) {
      this.root.position.addScaledVector(step, 1 / steps)
      const block = this.game.world.getBlock(this.root.position.x, this.root.position.y, this.root.position.z)
      if (block !== B.AIR && block !== B.LAVA && block !== B.WATER && block !== B.HONEY && block !== B.GLOWSHROOM && block !== B.CRYSTAL) {
        this.game.fx.spawnBurst(this.root.position, this.color, 8, 4, .1)
        return this.kill(false)
      }
      if (this.owner === 'player') {
        const hit = this.game.enemies.hitAt(this.root.position, this.radius + .3)
        if (hit) { hit.damage(this.damage); this.game.fx.spawnBurst(this.root.position, this.color, 14, 5, .12); return this.kill(false) }
        const boss = this.game.boss
        if (boss && !boss.dead && boss.root.position.distanceTo(this.root.position) < boss.radius + this.radius) {
          boss.damage(this.damage); this.game.fx.spawnBurst(this.root.position, this.color, 16, 6, .14); return this.kill(false)
        }
      } else {
        const p = this.game.player.position.clone(); p.y += .9
        if (p.distanceTo(this.root.position) < .85 + this.radius) {
          this.game.player.takeDamage(this.damage, 'a ranged attack', this.root.position)
          this.game.fx.spawnBurst(this.root.position, this.color, 12, 4, .12); return this.kill(false)
        }
      }
    }
    // orient
    if (this.kind === 'arrow' || this.kind === 'stinger') this.root.lookAt(this.root.position.clone().add(this.velocity))
    // trail
    this.trailTimer -= dt
    if (this.trailTimer <= 0) {
      this.trailTimer = .025
      this.trailPts.unshift(this.root.position.clone())
      if (this.trailPts.length > 8) this.trailPts.pop()
      const arr = this.trail.geometry.attributes.position.array
      for (let i = 0; i < 8; i++) {
        const p = this.trailPts[i] || this.root.position
        arr[i * 3] = p.x; arr[i * 3 + 1] = p.y; arr[i * 3 + 2] = p.z
      }
      this.trail.geometry.attributes.position.needsUpdate = true
    }
  }
  kill(burst = true) {
    if (this.dead) return
    this.dead = true
    if (burst) this.game.fx.spawnBurst(this.root.position, this.color, 12, 4, .12)
    this.game.scene.remove(this.root); this.game.scene.remove(this.trail)
    this.trail.geometry.dispose(); this.trail.material.dispose()
  }
}

export class ProjectileManager {
  constructor(game) { this.game = game; this.list = [] }
  spawn(opts) { const p = new Projectile(this.game, opts); this.list.push(p); return p }
  playerArrow(pos, dir, damage, color = 0xb4b0ff, speed = 38) {
    return this.spawn({ owner: 'player', kind: 'arrow', position: pos, velocity: dir.clone().multiplyScalar(speed), gravity: 5.5, damage, color, life: 3.5, radius: .1 })
  }
  playerMagic(pos, dir, damage, color = 0xd29bff) {
    return this.spawn({ owner: 'player', kind: 'bolt', position: pos, velocity: dir.clone().multiplyScalar(25), homing: 3.4, damage, color, life: 3.2, radius: .2 })
  }
  enemyBolt(pos, dir, damage, color = 0xff5a22, speed = 13) {
    return this.spawn({ owner: 'enemy', kind: 'bolt', position: pos, velocity: dir.clone().multiplyScalar(speed), gravity: 0, damage, color, life: 6, radius: .28 })
  }
  stinger(pos, dir, damage) {
    return this.spawn({ owner: 'enemy', kind: 'stinger', position: pos, velocity: dir.clone().multiplyScalar(22), gravity: 1.2, damage, color: 0xffd26a, life: 4, radius: .14 })
  }
  update(dt) {
    for (const p of this.list) p.update(dt)
    this.list = this.list.filter(p => !p.dead)
  }
  clearEnemyProjectiles() { this.list.forEach(p => { if (p.owner === 'enemy') p.kill(false) }); this.list = this.list.filter(p => !p.dead) }
}

/* ============================ ENEMIES ============================ */
export class Enemy {
