      for (const s of [-1, 1]) { const e = new THREE.Mesh(new THREE.SphereGeometry(.09, 6, 5), new THREE.MeshBasicMaterial({ color: 0xffd35a })); e.position.set(s * .24, .17, .38); head.add(e) }
