    this.pupil = new THREE.Mesh(new THREE.SphereGeometry(.58, 14, 10), new THREE.MeshBasicMaterial({ color: 0x120202 })); this.pupil.position.z = 2.45; this.root.add(this.pupil)
    this.mouth = new THREE.Group()
