      }
      this.game.audio.magic()
    }
    this.laserT -= dt
    if (this.phase === 1 && this.hp < this.maxHp * .5) { this.setPhase(2); this.game.audio.bossRoar(); this.game.ui.banner('PHASE II', 'THE WALL BLEEDS LIGHT') }
    if (this.phase === 2 && this.laserT <= 0) {
