  const Z = window.__ZENITH, g = Z.game, T = Z.THREE
  function inWorld(o) { let p = o; while (p) { if (p === g.world.group) return true; p = p.parent } return false }
  function ray(nx, ny) {
    const rc = new T.Raycaster()
    rc.setFromCamera(new T.Vector2(nx, ny), g.camera)
    const hits = rc.intersectObjects(g.scene.children, true).filter(h => inWorld(h.object))
    return hits.slice(0, 5).map(h => {
      const p = h.point
      const bx = Math.floor(p.x - .01), by = Math.floor(p.y - .01), bz = Math.floor(p.z - .01)
      const id = g.world.getBlock(bx, by, bz)
      return { dist: +h.distance.toFixed(2), pt: p.toArray().map(v => +v.toFixed(1)), block: id, blockName: Z.world.constructor ? id : '', tile: h.object.geometry?.attributes?.uv ? 'uv' : '?', mat: h.object.material?.type }
    })
  }
  return {
    left: ray(-.82, .2), farLeft: ray(-.98, 0), topLeft: ray(-.9, .5), center: ray(0, 0), centerUp: ray(0, .2), floor: ray(0, -.8),
