50: const SHAFT_VERT = `
51: varying vec2 vUv;
52: varying vec3 vWorld;
53: void main(){ vUv=uv; vec4 wp=modelMatrix*vec4(position,1.0); vWorld=wp.xyz; gl_Position=projectionMatrix*viewMatrix*wp; }
