55: const SHAFT_FRAG = `
56: uniform float uTime;
57: uniform vec3 uColor;
58: uniform float uStrength;
59: varying vec2 vUv;
60: varying vec3 vWorld;
61: float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
62: float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x),f.y);}
63: void main(){
64:   float edge = smoothstep(0.0,.22,vUv.x)*smoothstep(1.0,.78,vUv.x);
65:   float vertical = smoothstep(0.0,.16,vUv.y)*smoothstep(1.0,.65,vUv.y);
66:   float streaks = n(vec2(vUv.x*15.0+uTime*.05, vUv.y*5.0-uTime*.11));
67:   // fade the veil out when the camera steps inside it
68:   float nearFade = smoothstep(1.2, 6.0, distance(vWorld, cameraPosition));
69:   float a = edge*vertical*(.042 + streaks*.05)*uStrength*nearFade;
70:   gl_FragColor = vec4(uColor * (1.0+streaks*.5), a);
