75: uniform float uTime;
76: uniform vec2 uRes;
77: varying vec2 vUv;
78: float rand(vec2 co){ return fract(sin(dot(co,vec2(12.9898,78.233)))*43758.5453); }
79: void main(){
80:   vec2 uv = vUv;
81:   vec2 c = uv - .5;
82:   float r2 = dot(c,c);
83:   float ca = .0012 + r2*.0018;
84:   float r = texture2D(tDiffuse, uv + c*ca).r;
85:   float g = texture2D(tDiffuse, uv).g;
86:   float b = texture2D(tDiffuse, uv - c*ca).b;
87:   vec3 col = vec3(r,g,b);
