import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-gpu-sandbox']
})
const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 })
const errors = []
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()) })
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message))
await page.goto('http://localhost:3001', { waitUntil: 'load', timeout: 90000 })
await page.waitForTimeout(3000)
console.log('stats', await page.evaluate(() => window.__ZENITH.stats()))

// inventory preference
await page.keyboard.press('Tab')
await page.waitForTimeout(500)
console.log('inventory open', await page.evaluate(() => !document.getElementById('inventory').classList.contains('hidden')))
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/smoke-inv.png' })
await page.keyboard.press('Tab')
await page.waitForTimeout(300)

// mining test
const before = await page.evaluate(() => ({ blocks: window.__ZENITH.game.stats.blocks, pos: window.__ZENITH.player.position.toArray() }))
await page.evaluate(() => {
  const z = window.__ZENITH
  const p = z.player.position
  z.teleport(p.x, p.y, p.z)
  z.player.pitch = -0.9
  z.game.selected = 3 // pickaxe
  z.ui.setSelection()
  z.player.setMining(true)
})
await page.waitForTimeout(2500)
const after = await page.evaluate(() => ({ blocks: window.__ZENITH.game.stats.blocks, mining: !!window.__ZENITH.game.mining, pos: window.__ZENITH.player.position.toArray() }))
console.log('mine', before, after)
await page.evaluate(() => window.__ZENITH.player.setMining(false))

// combat: spawn a slime and hit it
const combat = await page.evaluate(async () => {
  const z = window.__ZENITH
  z.game.selected = 0; z.ui.setSelection()
  z.enemies.spawn('slime', z.player.position.clone().add(new z.THREE.Vector3(0, 0, -3)))
  const before = z.enemies.list.length
  z.player.attack()
  await new Promise(r => setTimeout(r, 400))
  return { enemyCount: before, enemies: z.enemies.list.map(e => ({ kind: e.kind, hp: e.hp })) }
})
console.log('combat', combat)

// boss
const boss = await page.evaluate(() => {
  const z = window.__ZENITH
  z.summon('eye')
  return { boss: z.game.boss?.name, hp: z.game.boss?.hp }
})
console.log('boss', boss)
await page.waitForTimeout(1200)
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/smoke-boss.png' })

console.log('stats2', await page.evaluate(() => window.__ZENITH.stats()))
console.log('errors', errors)
await browser.close()

